builder = r'''
from scipy.special import erf
def gelu(x): return 0.5*x*(1+erf(x/np.sqrt(2)))
def ffn_data(Lr):
    if Lr<5: return np.load(WORK/f'ffn_in_L{Lr}.npy')
    return np.load(WORK/'ffn_in_L5_cls.npy')
def build_layer(Lr, m, lam_rel, extra_A=None, score='var'):
    pre = f"roberta.encoder.layer.{Lr}."
    W1 = base(pre+"intermediate.dense.weight"); b1 = base(pre+"intermediate.dense.bias")
    W2 = base(pre+"output.dense.weight"); b2 = base(pre+"output.dense.bias")
    A = ffn_data(Lr) if extra_A is None else extra_A
    H = gelu(A@W1.T + b1)
    sc = H.var(0)*(W2**2).sum(0)
    keep = np.sort(np.argsort(-sc)[:m]); drop = np.setdiff1d(np.arange(3072), keep)
    Hk = H[:,keep]; mk = Hk.mean(0); T = H[:,drop]@W2[:,drop].T; mt = T.mean(0)
    if lam_rel is None:
        B = np.zeros((m,768))
    else:
        Xk = Hk-mk; G = Xk.T@Xk; lam = lam_rel*np.trace(G)/m
        B = np.linalg.solve(G+lam*np.eye(m), Xk.T@(T-mt))
    W2n = np.zeros_like(W2); W2n[:,keep] = W2[:,keep] + B.T
    b2n = b2 + mt - mk@B
    save_edit(pre+"output.dense.weight", W2n.astype(np.float32))
    save_edit(pre+"output.dense.bias", b2n.astype(np.float32))
    return keep.tolist()
def build_all(layers, m, lam=None):
    lam = lam or {}
    ffn_keep = {}
    for Lr in layers:
        ffn_keep[Lr] = build_layer(Lr, m, lam.get(Lr, 1.0 if Lr<5 else 0.1))
    return set_structure(layers=layers, ffn_keep=ffn_keep)
'''
open(WORK/'builder.py','w').write(builder)
exec(builder)
